import{_ as a,o as t,c as s,aa as o}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/academy/img/casti-stavby/05.webp",n="/buildary-help-preview/academy/img/casti-stavby/03.webp",h=JSON.parse('{"title":"Části stavby a výkresy","description":"","frontmatter":{"title":"Části stavby a výkresy"},"headers":[],"relativePath":"diary/projectparts.md","filePath":"diary/projectparts.md","lastUpdated":1794209661000}'),i={name:"diary/projectparts.md"};function l(v,e,k,u,d,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="casti-stavby-a-vykresy" tabindex="-1">Části stavby a výkresy <a class="header-anchor" href="#casti-stavby-a-vykresy" aria-label="Permalink to &quot;Části stavby a výkresy&quot;">​</a></h1><p>Stavbu můžete rozdělit na části – stavební objekty, podlaží a podobně – a ke každé části nahrát výkresy. Do výkresů pak značkou umisťujete úkoly i záznamy v deníku, takže je jasné, kterého místa se týkají.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/casti-stavby">Nahrát výkresy a rozdělit stavbu na části</a> v Akademii.</p><h2 id="k-cemu-casti-a-vykresy-slouzi" tabindex="-1">K čemu části a výkresy slouží <a class="header-anchor" href="#k-cemu-casti-a-vykresy-slouzi" aria-label="Permalink to &quot;K čemu části a výkresy slouží&quot;">​</a></h2><ul><li><strong>Stavební deník</strong> – u Provedených prací a Dalších záznamů označíte ve výkresu místo, kterého se záznam týká. Pole pro výkres se u záznamů zobrazí, když ho zapnete v <a href="/buildary-help-preview/diary/diarysettings">nastavení deníku</a>.</li><li><strong>Management úkolů</strong> – úkoly a vady zadáváte přímo do výkresu a pak je ve výkresech vyhledáváte – viz <a href="/buildary-help-preview/tickets/task_drawings">Výkresy a mapa</a>. Podle části stavby úkoly filtrujete v seznamu úkolů. Části stavby a výkresy můžete použít i jako podmínky pravidel, která u nového úkolu doplní Řešitele a Schvalovatele – viz <a href="/buildary-help-preview/tickets/rules">Kategorie, štítky a pravidla</a>.</li></ul><p>Části i výkresy jsou nepovinné. Bez nich deník i úkoly fungují, jen místo ve výkresu neoznačíte.</p><h2 id="rozdelit-stavbu-na-casti" tabindex="-1">Rozdělit stavbu na části <a class="header-anchor" href="#rozdelit-stavbu-na-casti" aria-label="Permalink to &quot;Rozdělit stavbu na části&quot;">​</a></h2><p>Otevřete <strong>Nastavení stavby</strong> a záložku <strong>Části stavby a výkresy</strong>. Na prvním řádku je celá stavba. Tlačítkem <strong>+</strong> na řádku přidáte pod tuto část další, podřízenou úroveň.</p><figure class="shot" style="--w:760px;"><img src="'+r+'" alt="Strom částí stavby s částí 2.NP a jejím výkresem" loading="lazy"></figure><ul><li>Na první úrovni doporučujeme členit stavbu na <strong>stavební objekty</strong>. Ty pak můžete dál dělit, například na podlaží.</li><li>U každé části je ikona s počtem jejích výkresů.</li><li>Ikonou tužky část upravíte, ikonou koše ji smažete. Tlačítky <strong>Rozbalit vše</strong> a <strong>Sbalit vše</strong> zobrazíte nebo skryjete celý strom.</li></ul><p>Promyšlené rozdělení stavby výrazně usnadní umisťování a pozdější vyhledávání úkolů.</p><h2 id="nahrat-vykresy" tabindex="-1">Nahrát výkresy <a class="header-anchor" href="#nahrat-vykresy" aria-label="Permalink to &quot;Nahrát výkresy&quot;">​</a></h2><p>Výkresy nahráváte v okně části stavby tlačítkem <strong>Nahrát výkres</strong>. Můžete jich vybrat několik najednou nebo je do okna přetáhnout.</p><figure class="shot" style="--w:760px;"><img src="'+n+'" alt="Okno Nová část stavby a výkresy s nahraným výkresem, tlačítky pro otočení a Nastavit výchozí výkres" loading="lazy"></figure><ul><li><strong>Formát:</strong> PDF nebo obrázek (JPG, PNG a podobně).</li><li><strong>Pořadí:</strong> výkresy se řadí podle názvu souboru.</li><li><strong>Otočení:</strong> před uložením výkres otočte šipkami pod náhledem tak, aby byl správně orientovaný. Později už orientaci nezměníte – nevyhovující výkres musíte smazat a nahrát znovu, a to ještě předtím, než ho někdo použije.</li><li><strong>Výchozí výkres:</strong> tlačítkem <strong>Nastavit výchozí výkres</strong> určíte, který výkres se u části nabízí jako první, bez ohledu na název souboru.</li></ul><div class="tip custom-block"><p class="custom-block-title">Nahrávání trvá</p><p>Výkres se po nahrání rozděluje na menší dílky, aby se s ním potom rychle pracovalo, proto nahrávání chvíli trvá. Nahráváte-li výkresy do více částí, otevřete aplikaci v několika oknech prohlížeče a nahrávejte souběžně.</p></div><h2 id="pouzite-vykresy" tabindex="-1">Použité výkresy <a class="header-anchor" href="#pouzite-vykresy" aria-label="Permalink to &quot;Použité výkresy&quot;">​</a></h2><p>Výkres, který už je použitý v některém záznamu nebo úkolu, nejde smazat. Můžete ho jen zneplatnit – pak se už nebude nabízet.</p>',18)])])}const m=a(i,[["render",l]]);export{h as __pageData,m as default};
